// Turn the uploaded PDF into a base64 data URI for Mistral OCR, and carry the
// chosen language forward so the parser node can pick the right structure family.
const item = $input.first();
const binKeys = Object.keys(item.binary || {});
if (!binKeys.length) throw new Error('No file was uploaded in the form.');
const key = binKeys[0];

let b64;
try {
  const buffer = await this.helpers.getBinaryDataBuffer(0, key);
  b64 = buffer.toString('base64');
} catch (e) {
  b64 = item.binary[key].data; // fallback: base64 already present on the binary
}

const language = item.json['Language'] || 'Chinese';
const fileName = (item.binary[key] && item.binary[key].fileName) || 'document.pdf';

return [{ json: {
  dataUri: 'data:application/pdf;base64,' + b64,
  language,
  fileName,
} }];

/**
 * legal_structure_parser.js
 * ---------------------------------------------------------------------------
 * Family-aware structural parser for Chinese (+ FR / EN / DE / ES) legal,
 * regulatory, official and technical documents.
 *
 * Strategy (the key idea):
 *   The SAME glyph means different things in different document families.
 *   "1." is a 目 in a statute, a sub-point in an official document, and a
 *   clause in a national standard. "（一）" is a 项 in a law but an L2 heading
 *   in a circular. So we DETECT THE FAMILY FIRST, then apply that family's
 *   hierarchy ladder.
 *
 *   1. classifyFamily(md)  -> picks one of:
 *        cn_legislative | cn_gongwen | cn_standards | latin_legislative | generic
 *   2. parseStructure(md)  -> flat list of records, splitting only down to that
 *        family's natural "record depth"; everything deeper folds into contenu.
 *
 * Output record:
 *   { article, contenu, level, label, family, num }
 *   - article : the header (Title / Chapter / Section / Article / clause ...)
 *   - contenu : its content (paragraphs / items / definitions / sub-clauses)
 *   - level   : depth in that family's ladder (1 = top)
 *   - label   : canonical unit name (chapter / article / item / clause / L1 ...)
 *   - family  : which master system was detected
 *   - num     : the marker's number as an integer when parseable, else null
 *   - para    : paragraph index within the article (1-based)
 *   Want strictly {article, contenu}? Drop the extra keys (see n8n block).
 *
 * Two behaviours specific to Chinese text:
 *   - PARAGRAPH EXPLOSION (default): every natural paragraph (款) inside an
 *     article becomes its own row, all inheriting the same `article`.
 *     Disable with { explodeParagraphs: false } for one row per article.
 *   - STACKED DEFINITIONS (default): inside a 术语和定义 / Terms-and-definitions
 *     section, a term written on the line *after* its number is folded into the
 *     `article` (e.g. "3.1" + "个人信息" -> article "3.1 个人信息"), with the
 *     definition paragraph as `contenu`. Disable with { definitions: false }.
 *
 * Options: { family?, maxDepth?, explodeParagraphs?, definitions?,
 *            paragraphMode?: 'line'(default) | 'block' | 'auto',
 *            standardsRollup? (cn_standards, default on), dropRolledHeadings? }
 *
 * Designed for an n8n Code node ("Run Once for All Items", JavaScript) fed the
 * Mistral OCR response (object with pages[].markdown). The pure functions are
 * also Node-testable (see the guarded export block at the bottom).
 * ---------------------------------------------------------------------------
 */


// 0. Numeral helpers
// ===========================================================================

// Chinese numeral characters (simplified + traditional + financial + arabic)
const CN_DIGITS = '零〇一二三四五六七八九十百千万两壹贰叁肆伍陆柒捌玖拾佰仟0-9';

function cnNumToInt(s) {
  if (s == null) return null;
  s = String(s).trim();
  if (/^\d+$/.test(s)) return parseInt(s, 10);
  const d = { 零:0,〇:0,一:1,壹:1,二:2,两:2,贰:2,三:3,叁:3,四:4,肆:4,五:5,伍:5,
              六:6,陆:6,七:7,柒:7,八:8,捌:8,九:9,玖:9 };
  const u = { 十:10,拾:10,百:100,佰:100,千:1000,仟:1000 };
  let total = 0, section = 0, num = 0, matched = false;
  for (const ch of s) {
    if (ch in d) { num = d[ch]; matched = true; }
    else if (ch in u) { if (num === 0) num = 1; section += num * u[ch]; num = 0; matched = true; }
    else return null; // unknown char -> not a clean numeral
  }
  return matched ? (section + num) : null;
}

function romanToInt(s) {
  if (!s || !/^[IVXLCDM]+$/i.test(s)) return null;
  s = s.toUpperCase();
  const v = { I:1, V:5, X:10, L:50, C:100, D:500, M:1000 };
  let n = 0;
  for (let i = 0; i < s.length; i++) {
    const c = v[s[i]], nx = v[s[i + 1]] || 0;
    n += c < nx ? -c : c;
  }
  return n;
}

// Normalise a Latin-script keyword: lowercase, strip accents, strip plural tail
function normKw(s) {
  return String(s).toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '') // drop combining accents
    .replace(/(es|s)$/, '');                          // chapitres -> chapitre
}

// ===========================================================================
// 1. THE MARKER TABLE   {marker -> family -> depth -> label}
//    Each family declares:
//      maxDepth : deepest level that becomes its own record by default
//      sig      : signature regexes (with weights) used for family detection
//      units    : (cnUnit style) unit-char -> {depth,label,container}
//      kwunits  : (kwUnit style) normalised-keyword -> {depth,label,container}
//      markers  : ordered match rules; FIRST match wins. Styles:
//         cnUnit  - capture[1] = Chinese unit char, looked up in `units`
//         kwUnit  - capture[1]=keyword 2=number 3=rest, keyword -> `kwunits`
//         decimal - capture[1]=dotted number 2=rest; depth = baseDepth + #dots
//         sym     - capture[1]=symbol marker 2=rest (German §)
//         token   - marker = whole match; rest = text after it
//    container=true  -> inline text after the marker is a TITLE (joins article)
//    container=false -> inline text after the marker is CONTENT (seeds contenu)
// ===========================================================================

const FAMILIES = {

  // -- System 1: 编/章/节/条/款/项/目 (Legislation Law art. 65) ----------------
  cn_legislative: {
    maxDepth: 4, // split down to 条 (article); 款/项/目 fold into contenu
    preamble: '前言',
    sig: [
      { re: new RegExp('第\\s*[' + CN_DIGITS + ']+\\s*条', 'g'), w: 5 }, // 条 is unique to law
      { re: new RegExp('第\\s*[' + CN_DIGITS + ']+\\s*[章节節編编]', 'g'), w: 2 },
    ],
    units: {
      '编':{depth:1,label:'part',container:true}, '編':{depth:1,label:'part',container:true},
      '分编':{depth:1,label:'subpart',container:true},
      '章':{depth:2,label:'chapter',container:true},
      '节':{depth:3,label:'section',container:true}, '節':{depth:3,label:'section',container:true},
      '条':{depth:4,label:'article',container:false}, '條':{depth:4,label:'article',container:false},
    },
    markers: [
      { style:'cnUnit', re: new RegExp('^第\\s*[' + CN_DIGITS + ']+\\s*(分编|编|章|节|条|編|節|條)') },
      { style:'token',  re: /^[（(]([一二三四五六七八九十百零〇两]+)[）)]\s*/, depth:6, label:'item',    container:false },
      { style:'token',  re: /^([0-9]+)\s*[.、．]\s*/,                          depth:7, label:'subitem', container:false },
    ],
  },

  // -- System 2: 一、/（一）/1./（1） (公文处理工作条例 + GB/T 9704) -------------
  cn_gongwen: {
    maxDepth: 1, // only 一、 is an article; （一）/1./（1） fold into contenu (one row each)
    preamble: '引言',
    sig: [
      { re: /^[一二三四五六七八九十百]+\s*、/gm, w: 2 },
      { re: /^[（(][一二三四五六七八九十百]+[）)]/gm, w: 1 },
    ],
    markers: [
      { style:'token', re: /^([一二三四五六七八九十百]+)\s*、\s*/,  depth:1, label:'L1', container:true  },
      { style:'token', re: /^[（(]([一二三四五六七八九十百]+)[）)]\s*/, depth:2, label:'L2', container:true  },
      { style:'token', re: /^([0-9]+)\s*[.．、]\s*/,               depth:3, label:'L3', container:false },
      { style:'token', re: /^[（(]([0-9]+)[）)]\s*/,               depth:4, label:'L4', container:false },
    ],
  },

  // -- System 3: 部分/章/条(decimal)/段/列项/附录 (GB/T 1.1-2020) --------------
  cn_standards: {
    maxDepth: 6, // split clause + all decimal sub-clauses; list items fold in
    preamble: '引言',
    sig: [
      { re: /^\s*\d+\.\d+/gm, w: 3 },
      { re: /规范性引用文件/g, w: 6 },
      { re: /^\s*1\s+范围/gm, w: 5 },
    ],
    markers: [
      { style:'token',   re: /^附\s*录\s*([A-Z])\b\s*/,                       depth:1, label:'annex',     container:true  },
      { style:'decimal', re: /^(\d+(?:\.\d+){1,5})(?:[ \t]+(.*))?$/, baseDepth:1, label:'subclause', container:true  },
      { style:'decimal', re: /^(\d+)[ \t]+(\S.*)$/,                  baseDepth:1, label:'clause',    container:true  },
      { style:'token',   re: /^[（(]?([a-z])[)）]\s+/,                          depth:7, label:'list-a',    container:false },
      { style:'token',   re: /^([0-9]+)[)）]\s+/,                              depth:8, label:'list-1',    container:false },
      { style:'token',   re: /^[—–-]{1,2}\s+/,                                depth:7, label:'list-dash', container:false },
      { style:'token',   re: /^[●·•・]\s?/,                                   depth:8, label:'list-dot',  container:false },
    ],
  },

  // -- Latin-script legislation (FR / EN / DE / ES) ---------------------------
  latin_legislative: {
    maxDepth: 6, // split down to Article / §; enumerations fold into contenu
    preamble: 'PREAMBULE',
    sig: [
      { re: /\b(article|artikel|art[íi]culo|chapitre|chapter|cap[íi]tulo|kapitel|secci[óo]n|abschnitt|titre|t[íi]tulo|livre|libro)\s+[0-9IVXLCDM]/gi, w: 3 },
    ],
    kwunits: {
      livre:{depth:1,label:'book',container:true},   book:{depth:1,label:'book',container:true},
      libro:{depth:1,label:'book',container:true},   buch:{depth:1,label:'book',container:true},
      titre:{depth:2,label:'title',container:true},  title:{depth:2,label:'title',container:true},
      titulo:{depth:2,label:'title',container:true}, titel:{depth:2,label:'title',container:true},
      partie:{depth:3,label:'part',container:true},  part:{depth:3,label:'part',container:true},
      parte:{depth:3,label:'part',container:true},   teil:{depth:3,label:'part',container:true},
      chapitre:{depth:4,label:'chapter',container:true}, chapter:{depth:4,label:'chapter',container:true},
      capitulo:{depth:4,label:'chapter',container:true}, kapitel:{depth:4,label:'chapter',container:true},
      section:{depth:5,label:'section',container:true},  seccion:{depth:5,label:'section',container:true},
      abschnitt:{depth:5,label:'section',container:true},
      article:{depth:6,label:'article',container:false}, artikel:{depth:6,label:'article',container:false},
      articulo:{depth:6,label:'article',container:false},
      paragraphe:{depth:6,label:'paragraph',container:false}, paragraph:{depth:6,label:'paragraph',container:false},
      parrafo:{depth:6,label:'paragraph',container:false},
    },
    markers: [
      { style:'kwUnit', re: /^([A-Za-zÀ-ÿ]+)\s+([0-9IVXLCDM]+[A-Za-z0-9.\-]*)\b[ \t]*[:.\-–—]?[ \t]*(.*)$/ },
      { style:'sym',    re: /^(§{1,2}\s*\d+[a-z]?)\b[ \t]*(.*)$/,            depth:6, label:'paragraph', container:false },
      { style:'token',  re: /^[（(]?([a-z])[)）][ \t]+/,                      depth:7, label:'enum-a', container:false },
      { style:'token',  re: /^([0-9]+)[.)）][ \t]+/,                         depth:7, label:'enum-1', container:false },
    ],
  },

  // -- Fallback: rely on markdown headings only -------------------------------
  generic: { maxDepth: 9, preamble: 'PREAMBULE', sig: [], markers: [] },
};

// ===========================================================================
// 2. Engine
// ===========================================================================

function unwrapMd(line) {
  const m = line.match(/^[ \t]{0,3}(#{1,6})[ \t]+(.*?)[ \t]*#*[ \t]*$/);
  return m ? { text: m[2], isMd: true } : { text: line, isMd: false };
}

function classifyFamily(md) {
  md = String(md);
  let best = 'generic', bestScore = 0;
  for (const fam of Object.keys(FAMILIES)) {
    const sig = FAMILIES[fam].sig || [];
    let score = 0;
    for (const s of sig) {
      const re = s.re.global ? s.re : new RegExp(s.re.source, s.re.flags + 'g');
      score += ((md.match(re) || []).length) * s.w;
    }
    if (score > bestScore) { bestScore = score; best = fam; }
  }
  return best;
}

function matchMarker(t, cfg) {
  for (const e of cfg.markers) {
    const m = t.match(e.re);
    if (!m) continue;

    if (e.style === 'cnUnit') {
      const u = cfg.units[m[1]];
      if (!u) continue;
      return { marker: m[0].trim(), remainder: t.slice(m[0].length).trim(),
               depth: u.depth, label: u.label, container: u.container };
    }
    if (e.style === 'kwUnit') {
      const u = cfg.kwunits[normKw(m[1])];
      if (!u) continue;
      return { marker: (m[1] + ' ' + m[2]).trim(), remainder: (m[3] || '').trim(),
               depth: u.depth, label: u.label, container: u.container };
    }
    if (e.style === 'decimal') {
      const dots = (m[1].match(/\./g) || []).length;
      return { marker: m[1], remainder: (m[2] || '').trim(),
               depth: e.baseDepth + dots, label: e.label, container: e.container };
    }
    if (e.style === 'sym') {
      return { marker: m[1].replace(/\s+/g, ' ').trim(), remainder: (m[2] || '').trim(),
               depth: e.depth, label: e.label, container: e.container };
    }
    // token
    return { marker: m[0].trim(), remainder: t.slice(m[0].length).trim(),
             depth: e.depth, label: e.label, container: e.container };
  }
  return null;
}

function extractNum(marker) {
  const s = marker || '';
  let m = s.match(/\d+/);
  if (m) return parseInt(m[0], 10);
  m = s.match(new RegExp('[' + CN_DIGITS + ']+'));
  if (m) { const n = cnNumToInt(m[0]); if (n != null) return n; }
  m = s.match(/[IVXLCDM]+/i);
  if (m) { const r = romanToInt(m[0]); if (r != null) return r; }
  return null;
}

// Headers that open a "terms and definitions" section (5 languages)
const DEFN_RE = /术语|定义|定義|definition|d[ée]finition|definici[oó]n|begriff/i;

// OCR noise: page footers like "—2—", "- 12 -", "第 3 页", "第3页/共8页"
const NOISE_RE = /^\s*(?:[—–‒\-~]{1,3}\s*\d{1,4}\s*[—–‒\-~]{1,3}|第\s*\d{1,4}\s*页(?:\s*[／/]\s*共\s*\d{1,4}\s*页)?)\s*$/;

// 公文 sub-heading written inline with its body: "（一）豁免末端治理设施。在同一个生产线内……"
// -> title "豁免末端治理设施", tail "在同一个生产线内……". Only splits on a SHORT lead
// sentence, so a normal paragraph that merely contains 。 is never chopped.
function splitInlineHeading(remainder) {
  const m = String(remainder).match(/^([^。！？]{1,40}?)[。]\s*(\S.*)$/);
  return m ? { title: m[1].trim(), tail: m[2].trim() } : { title: remainder, tail: '' };
}

// Any structural marker that must start a fresh line (used by dewrap).
const ANY_MARKER = /^(?:#{1,6}\s|第\s*[0-9一二三四五六七八九十百零〇两]+\s*[编編章节節条條]|[一二三四五六七八九十百]+\s*、|[（(][一二三四五六七八九十百]+[）)]|\d+(?:\.\d+)*[ \t.．、)）]|[（(]\d+[）)]|[a-z][)）]\s|§|附\s*[件录]|[—–-]{1,2}\s)/;
const HEADING_LINE = /^(?:附\s*[件录]\s*[0-9A-Z]*\s*[：:]?|填写说明|目\s*[录次])$/;

/**
 * Re-join hard-wrapped lines (pdftotext / scanned OCR) into paragraphs.
 * Mistral's markdown is usually already reflowed, so this is OFF by default;
 * enable with { dewrap: true } when a line-per-visual-row extraction is fed in.
 */
function dewrap(md) {
  const lines = String(md).replace(/\f/g, '\n').split(/\r?\n/)
    .map(l => l.trim())
    .filter(l => l && !NOISE_RE.test(l));           // drop footers first (they split words)
  const terminal = (s) => /[。！？；：:]$/.test(s) || (/[）】》]$/.test(s) && s.length <= 35);
  // a heading never ends mid-sentence (、，：), so those are wrapped enumeration lines
  const standalone = (s) => HEADING_LINE.test(s) ||
    (ANY_MARKER.test(s) && s.length <= 25 && !/[、，：,:]$/.test(s));
  const cont = (s) => /^[，、；：。）】》,;:]/.test(s);   // continuation: must attach to prev
  const out = [];
  for (const l of lines) {
    const prev = out[out.length - 1];
    const join = prev && (cont(l) ||
      (!terminal(prev) && !standalone(prev) && !ANY_MARKER.test(l)));
    if (join) out[out.length - 1] = prev + l;        // CJK: no space when joining
    else out.push(l);
  }
  return out.join('\n');
}

// Split an article body into paragraphs.
//   'block' : paragraphs are blank-line-separated blocks (a 款 may span lines)
//   'line'  : every non-empty line is its own paragraph
//   'auto'  : block when blank-line separators exist, else line (OCR-robust)
function toParagraphs(lines, mode = 'auto') {
  const nonEmpty = lines.filter(l => l.trim() !== '');
  if (!nonEmpty.length) return [];
  if (mode === 'line') return nonEmpty.map(l => l.trim());
  const hadBlank = lines.some(l => l.trim() === '');
  if (mode === 'auto' && !hadBlank) return nonEmpty.map(l => l.trim());
  const blocks = [];
  let buf = [];
  for (const l of lines) {
    if (l.trim() === '') { if (buf.length) { blocks.push(buf.join('\n').trim()); buf = []; } }
    else buf.push(l);
  }
  if (buf.length) blocks.push(buf.join('\n').trim());
  return blocks.filter(Boolean);
}

/**
 * Parse OCR markdown into a flat list of structural rows.
 * @param {string} md
 * @param {object} [opts]  see header for the full option list
 */
function parseStructure(md, opts = {}) {
  if (opts.dewrap) md = dewrap(md);
  const family = opts.family || classifyFamily(md);
  const cfg = FAMILIES[family] || FAMILIES.generic;
  const maxDepth = opts.maxDepth != null ? opts.maxDepth : cfg.maxDepth;
  const explode = opts.explodeParagraphs !== false; // default: one row per paragraph
  const handleDefns = opts.definitions !== false;   // default: stacked-term handling
  const paraMode = opts.paragraphMode || 'line';    // 'line' = each non-empty line is a row
  // Split a container header's title into contenu (第一章 总则 -> "第一章" + "总则").
  // Default on for cn_legislative; off elsewhere. Leaf units (条/项) are unaffected.
  const splitHeads = opts.splitHeaderTitle != null ? opts.splitHeaderTitle
                                                   : family === 'cn_legislative';
  // 公文 headings carry their body on the same line after 。 -> keep only the title in article
  const headSent = opts.headingSentenceSplit != null ? opts.headingSentenceSplit
                                                     : family === 'cn_gongwen';
  const stripNoise = opts.stripNoise !== false;     // drop page footers by default

  // ---- Pass 1: collect article-level blocks (header + raw body lines) ----
  const blocks = [];
  let cur = null, defnsDepth = null;
  const push = () => { if (cur) blocks.push(cur); };
  const open = (b) => { push(); cur = b; };

  for (const raw of String(md).split(/\r?\n/)) {
    if (stripNoise && NOISE_RE.test(raw)) continue;                     // page footer -> drop
    const { text, isMd } = unwrapMd(raw);
    const t = text.trim();
    const hit = t ? matchMarker(t, cfg) : null;

    if (hit && hit.depth <= maxDepth) {
      if (defnsDepth != null && hit.depth <= defnsDepth) defnsDepth = null; // left defns section
      let title = hit.remainder, tail = '';
      if (headSent && hit.container && title) {                         // "（一）小标题。正文……"
        const s = splitInlineHeading(title); title = s.title; tail = s.tail;
      }
      const split = splitHeads && hit.container; // container title -> contenu, not article
      open({
        marker: hit.marker,
        article: (hit.container && !split) ? (title ? hit.marker + ' ' + title : hit.marker)
                                           : hit.marker,
        level: hit.depth, label: hit.label, container: hit.container,
        hadInline: !!(hit.remainder), num: extractNum(hit.marker),
        inDefns: handleDefns && defnsDepth != null, body: [],
      });
      if (split && title) cur.body.push(title);                          // 章/节 title -> contenu
      else if (!hit.container && hit.remainder) cur.body.push(hit.remainder); // leaf: inline = first 款
      if (tail) cur.body.push(tail);                                     // 公文 inline body
      if (handleDefns && DEFN_RE.test(title)) defnsDepth = hit.depth;    // this header opens defns
    } else if (isMd && t) {
      open({ marker: '', article: t, level: 1, label: 'heading', container: true,
             hadInline: true, num: null, inDefns: false, body: [] });
    } else if (cur) {
      cur.body.push(raw); // keep raw line (incl. blank lines + deeper markers)
    } else if (t) {
      open({ marker: '', article: cfg.preamble || 'PREAMBULE', level: 0, label: 'preamble',
             container: false, hadInline: false, num: null, inDefns: false, body: [raw] });
    }
  }
  push();

  // ---- Pass 2: render blocks into {article, contenu} rows ----
  const rows = [];
  const row = (b, article, contenu, para) =>
    ({ article, contenu: (contenu || '').trim(),
       level: b.level, label: b.label, family, num: b.num, para });
  const pushRows = (b, article, body) => {
    const paras = explode ? toParagraphs(body, paraMode)
                          : [body.join('\n').trim()].filter(Boolean);
    if (!paras.length) rows.push(row(b, article, '', 1));
    else paras.forEach((p, i) => rows.push(row(b, article, p, i + 1)));
  };
  // definition-aware (article, body) for a block
  const defResolve = (b) => {
    let article = b.article, body = b.body;
    if (b.inDefns && b.container && !b.hadInline && body.length) {
      const term = body[0].trim();
      article = term ? b.marker + ' ' + term : b.marker;
      body = body.slice(1);
    }
    return { article, body };
  };

  const rollup = family === 'cn_standards' && opts.standardsRollup !== false;
  if (!rollup) {
    for (const b of blocks) { const r = defResolve(b); pushRows(b, r.article, r.body); }
    return rows;
  }

  // ---- Standards roll-up ----
  // Per top-level clause, the article level = max(1, deepest level in that clause - 1).
  // Headings at the article level are articles; a shallower clause that only holds
  // sub-clauses becomes a header row with empty contenu; anything deeper than the
  // article level rolls up into its ancestor at the article level. 术语和定义 entries
  // are left untouched (each term keeps its own article).
  const isDec = (b) => b.label === 'clause' || b.label === 'subclause';
  const path = (b) => b.marker.split('.');
  const level = (b) => path(b).length;
  const topKey = (b) => path(b)[0];                       // clause id (first path component)
  const decs = blocks.filter(isDec);
  const dropHeads = opts.dropRolledHeadings === true;

  const clauseMaxD = new Map();
  for (const b of decs) if (!b.inDefns) {
    const k = topKey(b);
    clauseMaxD.set(k, Math.max(clauseMaxD.get(k) || 1, level(b)));
  }
  const articleLevel = (b) => Math.max(1, (clauseMaxD.get(topKey(b)) || 1) - 1);
  const ownerKey = (b) => { const AL = articleLevel(b);
    return level(b) > AL ? path(b).slice(0, AL).join('.') : b.marker; };

  const groups = new Map();      // article marker -> { block, lines:[] }
  const items = [];              // ordered render units
  let pos = 0;
  for (const b of blocks) {
    const p = pos++;
    if (b.inDefns) {                                    // keep per-term definition articles
      const r = defResolve(b);
      items.push({ pos: p, block: b, article: r.article, body: r.body });
    } else if (isDec(b)) {
      const owner = ownerKey(b);
      if (owner === b.marker) {                         // this clause IS its own article
        if (!groups.has(b.marker)) { groups.set(b.marker, { block: b, lines: [] });
                                     items.push({ pos: p, key: b.marker }); }
        groups.get(b.marker).lines.push(...b.body);
      } else {                                          // deeper than article level -> roll up
        if (!groups.has(owner)) { const ob = decs.find(x => x.marker === owner && !x.inDefns);
                                  groups.set(owner, { block: ob || b, lines: [] });
                                  items.push({ pos: p, key: owner }); }
        const g = groups.get(owner);
        if (!dropHeads) g.lines.push(b.article);        // keep "4.2.1 访问控制" line (lossless)
        g.lines.push(...b.body);
      }
    } else {                                            // preamble / annex / heading
      const r = defResolve(b);
      items.push({ pos: p, block: b, article: r.article, body: r.body });
    }
  }
  items.sort((a, b) => a.pos - b.pos);
  for (const it of items) {
    if (it.key != null) { const g = groups.get(it.key); pushRows(g.block, g.block.article, g.lines); }
    else pushRows(it.block, it.article, it.body);
  }
  return rows;
}

// Convenience: full pipeline from an OCR response object -> records
function recordsFromOcr(ocr, opts) {
  const md = (ocr && ocr.pages ? ocr.pages : []).map(p => (p && p.markdown) || '').join('\n');
  return parseStructure(md, opts);
}

