const LANG_TO_FAMILY = {
  Chinese: null,                 // auto-detect among the 3 Chinese systems
  French:  'latin_legislative',
  English: 'latin_legislative',
  German:  'latin_legislative',
  Spanish: 'latin_legislative',
};

const ocr = $input.first().json;
let language = 'Chinese';
try { language = $('Prepare OCR request').first().json.language || 'Chinese'; } catch (e) {}

const forced = LANG_TO_FAMILY[language];           // null => auto-detect
const opts = forced ? { family: forced } : {};     // tune here: maxDepth, paragraphMode, etc.

// One n8n item per { article, contenu, level, label, family, num, para }.
// For strictly {article, contenu}, replace r with { article: r.article, contenu: r.contenu }.
return recordsFromOcr(ocr, opts).map(r => ({ json: r }));
